    size_t pos = 0;

    void skip() {
        while (pos < s.size() && (s[pos] == ' ' || s[pos] == ',' || s[pos] == '\t')) pos++;
    }

    string nextToken() {
        skip();
        if (pos >= s.size()) return "";
        if (s[pos] == '[') {
            int depth = 0;
            size_t start = pos;
            while (pos < s.size()) {
                char c = s[pos++];
                if (c == '[') depth++;
                else if (c == ']') {
                    depth--;
                    if (depth == 0) break;
                }
            }
            return s.substr(start, pos - start);
        }
        size_t start = pos;
        while (pos < s.size() && s[pos] != ',' && s[pos] != ']') pos++;
        return s.substr(start, pos - start);
    }
};

vector<string> splitTop(const string& s) {
    vector<string> parts;
    int depth = 0;
    size_t start = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '[') depth++;
        else if (s[i] == ']') depth--;
        else if (s[i] == ',' && depth == 0) {
            parts.push_back(s.substr(start, i - start));
            start = i + 1;
        }
    }
    parts.push_back(s.substr(start));
    return parts;
}

vector<int> readIntVec(const string& text) {
    string s = text;
    if (s == "[]") return {};
    string inner = s.substr(1, s.size() - 2);
    vector<string> parts = splitTop(inner);
    vector<int> result;
    for (const string& p : parts) {
        if (!p.empty()) result.push_back(stoi(p));
    }
    return result;
}

vector<vector<int>> readInt2D(const string& text) {
    if (text == "[]") return {};
    string inner = text.substr(1, text.size() - 2);
    vector<string> rows = splitTop(inner);
    vector<vector<int>> result;
    for (const string& row : rows) result.push_back(readIntVec(row));
    return result;
}

