#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *s;
    int pos;
    int len;
} Tok;

static void skip_ws(Tok *t) {
    while (t->pos < t->len &&
           (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
            t->s[t->pos] == '\t' || t->s[t->pos] == '\n' || t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char *next_token(Tok *t) {
    skip_ws(t);
    if (t->pos >= t->len) return NULL;

    int start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' && t->s[t->pos] != ']') t->pos++;
    }

    int n = t->pos - start;
    char *out = (char *)malloc((size_t)n + 1);
    memcpy(out, t->s + start, (size_t)n);
    out[n] = '\0';
    return out;
}

static int parse_int(Tok *t) {
    char *token = next_token(t);
    int value = atoi(token);
    free(token);
    return value;
}

static int parse_int_array(const char *text, int **out) {
    int len = (int)strlen(text);
    if (len <= 2) {
        *out = NULL;
        return 0;
    }

    char *inner = (char *)malloc((size_t)len - 1);
    memcpy(inner, text + 1, (size_t)len - 2);
    inner[len - 2] = '\0';

    int count = 1;
    for (int i = 0; inner[i]; ++i) if (inner[i] == ',') count++;

    int *arr = (int *)malloc((size_t)count * sizeof(int));
    Tok tok = {inner, 0, (int)strlen(inner)};
    for (int i = 0; i < count; ++i) arr[i] = parse_int(&tok);

    free(inner);
    *out = arr;
    return count;
}

static int parse_int_2d(Tok *t, int ***out_rows, int **out_cols) {
    char *token = next_token(t);
    int len = (int)strlen(token);

    if (len <= 2) {
        *out_rows = NULL;
        *out_cols = NULL;
        free(token);
        return 0;
    }

    char *inner = (char *)malloc((size_t)len - 1);
    memcpy(inner, token + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(token);

    int rows = 0, depth = 0;
    for (int i = 0; inner[i]; ++i) {
        if (inner[i] == '[') {
            if (depth == 0) rows++;
            depth++;
        } else if (inner[i] == ']') {
            depth--;
        }
    }

    int **matrix = (int **)malloc((size_t)rows * sizeof(int *));
    int *cols = (int *)malloc((size_t)rows * sizeof(int));

    Tok rowTok = {inner, 0, (int)strlen(inner)};
    for (int i = 0; i < rows; ++i) {
        char *row = next_token(&rowTok);
        cols[i] = parse_int_array(row, &matrix[i]);
        free(row);
    }

    free(inner);
    *out_rows = matrix;
    *out_cols = cols;
    return rows;
}

typedef struct {
    int id;
    int rating;
} Item;

static int compare_items(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;
    if (x->rating != y->rating) return (y->rating > x->rating) - (y->rating < x->rating);
    return (y->id > x->id) - (y->id < x->id);
}

int *filterRestaurants(int **restaurants, int restaurantsSize, int *restaurantsColSize,
                       int veganFriendly, int maxPrice, int maxDistance, int *returnSize) {
    (void)restaurantsColSize;

    Item *items = (Item *)malloc((size_t)restaurantsSize * sizeof(Item));
    int count = 0;

    for (int i = 0; i < restaurantsSize; ++i) {
        int *r = restaurants[i];
        if ((veganFriendly == 0 || r[2] == 1) &&
            r[3] <= maxPrice &&
            r[4] <= maxDistance) {
            items[count].id = r[0];
            items[count].rating = r[1];
            count++;
        }
    }

    qsort(items, (size_t)count, sizeof(Item), compare_items);

    int *answer = (int *)malloc((size_t)count * sizeof(int));
    for (int i = 0; i < count; ++i) answer[i] = items[i].id;

    free(items);
    *returnSize = count;
    return answer;
}

